let activeGroup='all';
let currentResults=[];
let selected=null;
let showFavoritesOnly=false;
const favorites=new Set(JSON.parse(localStorage.getItem('geonature-favorites')||'[]').map(Number));
const imageCache=new Map();
const imageRequests=new Map();
const $=id=>document.getElementById(id);

function normalizeText(value){
  return String(value ?? '').toLocaleLowerCase('ka-GE').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
}
function searchableText(item){
  return normalizeText([item.ka,item.en,item.latin,item.group,item.habitat,item.regions,item.season,item.active,item.desc,...(item.tags||[])].join(' '));
}
function groupIcon(group){return group==='ფრინველი'?'🐦':group==='ძუძუმწოვარი'?'🦌':'🐟';}
function matches(item,query){
  const q=normalizeText(query);
  if(!q)return true;
  const text=searchableText(item);
  if(text.includes(q))return true;
  return q.split(/\s+/).filter(Boolean).every(word=>text.includes(word));
}
function saveFavorites(){localStorage.setItem('geonature-favorites',JSON.stringify([...favorites]));}
function toggleFavorite(id){
  if(favorites.has(id))favorites.delete(id);else favorites.add(id);
  saveFavorites();
  updateFavoriteCount();
  renderResults();
  if(selected && selected.id===id)openDetail(id,true);
}
function updateFavoriteCount(){$('favoriteCount').textContent=String(favorites.size);}
function countGroups(){
  const all=GEO_SPECIES.length;
  const birds=GEO_SPECIES.filter(x=>x.group==='ფრინველი').length;
  const mammals=GEO_SPECIES.filter(x=>x.group==='ძუძუმწოვარი').length;
  const fish=GEO_SPECIES.filter(x=>x.group==='თევზი').length;
  $('statAll').textContent=all;$('statBird').textContent=birds;$('statMammal').textContent=mammals;$('statFish').textContent=fish;
  $('countAll').textContent=`(${all})`;$('countBird').textContent=`(${birds})`;$('countMammal').textContent=`(${mammals})`;$('countFish').textContent=`(${fish})`;
}
function searchScore(item,query){
  const q=normalizeText(query);if(!q)return 0;
  const fields=[['ka',item.ka,100],['en',item.en,80],['latin',item.latin,70],['regions',item.regions,35],['habitat',item.habitat,30],['tags',(item.tags||[]).join(' '),25]];
  let best=0;
  fields.forEach(([name,value,weight])=>{const t=normalizeText(value);if(t===q)best=Math.max(best,weight+50);else if(t.startsWith(q))best=Math.max(best,weight+35);else if(t.includes(q))best=Math.max(best,weight);});
  return best;
}
function getResults(query){
  let items=GEO_SPECIES.filter(item=>activeGroup==='all'||item.group===activeGroup);
  if(showFavoritesOnly)items=items.filter(item=>favorites.has(item.id));
  if(query.trim())items=items.filter(item=>matches(item,query)).sort((a,b)=>searchScore(b,query)-searchScore(a,query));
  return items;
}
function imageSearchUrl(item){
  const query=encodeURIComponent(item.latin||item.en||item.ka);
  return `https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch=${query}&gsrnamespace=6&gsrlimit=1&prop=imageinfo&iiprop=url|mime&iiurlwidth=960&format=json&origin=*`;
}
async function loadImage(item){
  if(imageCache.has(item.id))return imageCache.get(item.id);
  if(imageRequests.has(item.id))return imageRequests.get(item.id);
  const promise=fetch(imageSearchUrl(item),{mode:'cors'})
    .then(r=>{if(!r.ok)throw new Error('image api');return r.json()})
    .then(data=>{
      const pages=data?.query?.pages?Object.values(data.query.pages):[];
      const info=pages.find(p=>p.imageinfo?.[0]?.url)?.imageinfo?.[0];
      const result=info?{src:info.thumburl||info.url,credit:'Wikimedia Commons'}:null;
      imageCache.set(item.id,result);return result;
    }).catch(()=>{imageCache.set(item.id,null);return null})
    .finally(()=>imageRequests.delete(item.id));
  imageRequests.set(item.id,promise);return promise;
}
function imageShell(item){return `<div class="u-image-pro" data-image-id="${item.id}"><div class="image-placeholder-pro"><span>${item.icon}</span><small>სურათი იტვირთება…</small></div><img class="u-photo-pro" alt="${item.ka}" loading="lazy" decoding="async"></div>`;}
async function hydrateCardImage(card,item){
  const img=card.querySelector('.u-photo-pro');const wrap=card.querySelector('.u-image-pro');if(!img||wrap.dataset.loaded==='1')return;
  wrap.dataset.loaded='1';
  const result=await loadImage(item);
  if(result?.src){img.src=result.src;img.classList.add('ready');wrap.classList.add('has-image');wrap.dataset.credit=result.credit||'';}
  else wrap.classList.add('no-image');
}
function observeImages(){
  const cards=[...document.querySelectorAll('.u-card-pro')];
  if('IntersectionObserver' in window){
    const observer=new IntersectionObserver(entries=>{
      entries.forEach(entry=>{if(entry.isIntersecting){const card=entry.target;const item=GEO_SPECIES.find(x=>x.id===Number(card.dataset.id));if(item)hydrateCardImage(card,item);observer.unobserve(card);}});
    },{rootMargin:'360px'});
    cards.forEach(card=>observer.observe(card));
  }else cards.forEach(card=>hydrateCardImage(card,GEO_SPECIES.find(x=>x.id===Number(card.dataset.id))));
}
function renderQuick(){
  const labels=['მწყერი','ხოხობი','კაკაბი','არწივი','მურა დათვი','მგელი','კალმახი','კობრი','ლოქო'];
  $('quickPills').innerHTML=labels.map(label=>`<button type="button" class="quick-pill">${label}</button>`).join('');
  $('quickPills').querySelectorAll('.quick-pill').forEach(btn=>btn.onclick=()=>{const input=$('universalSearch');input.value=btn.textContent;activeGroup='all';syncFilters();renderResults();input.focus();});
}
function renderSuggestions(query){
  const box=$('liveSuggestions');const q=query.trim();
  if(!q){box.hidden=true;box.innerHTML='';return;}
  const items=GEO_SPECIES.filter(item=>matches(item,q)).sort((a,b)=>searchScore(b,q)-searchScore(a,q)).slice(0,8);
  box.innerHTML=items.length?items.map(item=>`<button type="button" data-suggest-id="${item.id}"><span class="suggest-icon">${groupIcon(item.group)}</span><span><b>${item.ka}</b><small>${item.en} · ${item.group}</small></span><span class="suggest-arrow">›</span></button>`).join(''):`<div class="suggest-empty">სწრაფი შედეგი ვერ მოიძებნა</div>`;
  box.hidden=false;
  box.querySelectorAll('[data-suggest-id]').forEach(btn=>btn.onclick=()=>{const id=Number(btn.dataset.suggestId);openDetail(id);box.hidden=true;});
}
function renderResults(){
  const query=$('universalSearch').value.trim();currentResults=getResults(query);
  $('resultCount').textContent=query?`${currentResults.length} შედეგი`:`${currentResults.length} სახეობა`;
  $('resultHint').textContent=showFavoritesOnly?'რჩეული სახეობები':query?`ძიება: „${query}“`:'აირჩიე ბარათი დეტალური პროფილისთვის';
  $('activeChips').innerHTML=`${activeGroup!=='all'?`<button class="active-chip" data-clear-group>კატეგორია: ${activeGroup} ×</button>`:''}${showFavoritesOnly?`<button class="active-chip" data-clear-fav>★ მხოლოდ რჩეულები ×</button>`:''}`;
  $('resultGrid').innerHTML=currentResults.length?currentResults.map(item=>`<article class="u-card-pro" data-id="${item.id}" tabindex="0" role="button"><div class="card-image-wrap">${imageShell(item)}<button class="star-btn ${favorites.has(item.id)?'on':''}" type="button" data-star="${item.id}" aria-label="რჩეულებში ${item.ka}">${favorites.has(item.id)?'★':'☆'}</button><span class="group-badge">${groupIcon(item.group)} ${item.group}</span></div><div class="u-body-pro"><div class="latin-line"><span>${item.latin}</span><span>#{String(item.id).padStart(2,'0')}</span></div><h3>${item.ka}</h3><p class="english-name">${item.en}</p><div class="card-facts"><span>📍 ${item.regions.split(',')[0]}</span><span>🕒 ${item.active.split(' ')[0]}</span></div><div class="tag-row">${(item.tags||[]).slice(0,3).map(tag=>`<span>${tag}</span>`).join('')}</div></div></article>`).join(''):`<div class="empty-pro"><div class="empty-icon">🔎</div><h3>შედეგი ვერ მოიძებნა</h3><p>სცადე ქართული, ინგლისური ან ლათინური სახელის ნაწილი.</p><button class="btn primary" id="resetSearch" type="button">ყველას ჩვენება</button></div>`;
  $('resultGrid').querySelectorAll('.u-card-pro').forEach(card=>{
    const id=Number(card.dataset.id);card.onclick=e=>{if(e.target.closest('[data-star]'))return;openDetail(id);};
    card.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('[data-star]')){e.preventDefault();openDetail(id);}};
  });
  $('resultGrid').querySelectorAll('[data-star]').forEach(btn=>btn.onclick=e=>{e.stopPropagation();toggleFavorite(Number(btn.dataset.star));});
  $('activeChips').querySelector('[data-clear-group]')?.addEventListener('click',()=>{activeGroup='all';syncFilters();renderResults();});
  $('activeChips').querySelector('[data-clear-fav]')?.addEventListener('click',()=>{showFavoritesOnly=false;updateFavoriteToggle();renderResults();});
  $('resetSearch')?.addEventListener('click',()=>{activeGroup='all';showFavoritesOnly=false;$('universalSearch').value='';syncFilters();updateFavoriteToggle();renderResults();});
  renderSuggestions(query);observeImages();
}
async function openDetail(id,keepFilter=false){
  selected=GEO_SPECIES.find(item=>item.id===id);if(!selected)return;
  if(!keepFilter){activeGroup=selected.group;syncFilters();}
  const isFav=favorites.has(selected.id);
  $('detailPanel').innerHTML=`<div class="detail-cover-pro"><div class="detail-photo-loading">${selected.icon}<span>სურათი იტვირთება…</span></div><img id="detailSpeciesImage" alt="${selected.ka}"><button id="detailImageButton" class="image-action" type="button" disabled>🔍 დიდი ფოტო</button><button id="detailFavButton" class="detail-fav ${isFav?'on':''}" type="button">${isFav?'★ რჩეულებში':'☆ რჩეულებში'}</button></div><div class="detail-head-pro"><div><span class="u-tag">${groupIcon(selected.group)} ${selected.group}</span><h2>${selected.ka}</h2><p>${selected.en} · <i>${selected.latin}</i></p></div></div><div class="detail-summary-pro">${selected.desc}</div><div class="detail-facts-pro"><div><small>ჰაბიტატი</small><b>🌿 ${selected.habitat}</b></div><div><small>გავრცელება</small><b>📍 ${selected.regions}</b></div><div><small>სეზონი</small><b>📅 ${selected.season}</b></div><div><small>აქტივობა</small><b>🕒 ${selected.active}</b></div></div><div class="detail-actions-pro"><a class="btn primary" href="map.html?species=${encodeURIComponent(selected.ka)}">🗺️ რუკაზე ნახვა</a><button class="btn ghost" id="copySpeciesLink" type="button">🔗 გაზიარება</button></div><div class="detail-tags-pro">${(selected.tags||[]).map(tag=>`<span># ${tag}</span>`).join('')}</div><div class="source-box-pro"><small>სურათის წყარო</small><p>ონლაინ ფოტო იტვირთება Wikimedia Commons-იდან. წყაროს წარწერა ინახება ფოტოს გახსნისას.</p></div>`;
  $('detailFavButton').onclick=()=>toggleFavorite(selected.id);
  $('copySpeciesLink').onclick=async()=>{const url=`${location.href.split('#')[0]}#species=${selected.id}`;try{await navigator.clipboard.writeText(url);$('copySpeciesLink').textContent='✓ დაკოპირდა';setTimeout(()=>$('copySpeciesLink').textContent='🔗 გაზიარება',1200);}catch{location.hash=`species=${selected.id}`;}};
  const result=await loadImage(selected);const img=$('detailSpeciesImage');
  if(result?.src){img.src=result.src;img.classList.add('ready');$('detailPanel').querySelector('.detail-photo-loading').classList.add('hide');$('detailImageButton').disabled=false;$('detailImageButton').onclick=()=>openImageModal(result.src,selected.ka,selected.latin,result.credit);}
  else $('detailPanel').querySelector('.detail-photo-loading span').textContent='ონლაინ ფოტო ვერ ჩაიტვირთა';
  $('detailPanel').scrollIntoView({behavior:'smooth',block:'start'});
}
function openImageModal(src,title,latin,credit){$('modalImage').src=src;$('modalImage').alt=title;$('modalTitle').textContent=title;$('modalLatin').textContent=latin||'';$('modalCredit').textContent=credit||'';$('imageModal').classList.add('open');$('imageModal').setAttribute('aria-hidden','false');}
function closeImageModal(){$('imageModal').classList.remove('open');$('imageModal').setAttribute('aria-hidden','true');$('modalImage').src='';}
function syncFilters(){document.querySelectorAll('.filter').forEach(btn=>btn.classList.toggle('active',btn.dataset.group===activeGroup));}
function updateFavoriteToggle(){$('favoritesToggle').classList.toggle('selected',showFavoritesOnly);$('favoritesToggle').innerHTML=`★ რჩეულები <span id="favoriteCount">${favorites.size}</span>`;}
function randomSpecies(){const pool=getResults('');if(!pool.length)return;const pick=pool[Math.floor(Math.random()*pool.length)];$('universalSearch').value=pick.ka;renderResults();openDetail(pick.id);}
function initSearch(){
  countGroups();updateFavoriteCount();updateFavoriteToggle();renderQuick();renderResults();
  const input=$('universalSearch');
  input.addEventListener('input',()=>renderResults());
  input.addEventListener('focus',()=>renderSuggestions(input.value));
  $('clearSearch').onclick=()=>{input.value='';renderResults();input.focus();};
  document.querySelectorAll('.filter').forEach(btn=>btn.onclick=()=>{activeGroup=btn.dataset.group;showFavoritesOnly=false;updateFavoriteToggle();syncFilters();renderResults();});
  $('randomSpecies').onclick=randomSpecies;
  $('favoritesToggle').onclick=()=>{showFavoritesOnly=!showFavoritesOnly;updateFavoriteToggle();renderResults();};
  input.addEventListener('keydown',e=>{if(e.key==='Enter'&&currentResults[0])openDetail(currentResults[0].id);if(e.key==='Escape')$('liveSuggestions').hidden=true;});
  document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();input.focus();}if(e.key==='Escape')closeImageModal();});
  document.addEventListener('click',e=>{if(!e.target.closest('#smartSearch'))$('liveSuggestions').hidden=true;if(e.target.matches('[data-close-modal]'))closeImageModal();});
  const hash=location.hash.match(/species=(\d+)/);if(hash){setTimeout(()=>openDetail(Number(hash[1])),150);}
}
document.addEventListener('DOMContentLoaded',()=>{if($('universalSearch'))initSearch();});

